head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > focusMode]<br/>GridView 컴포넌트의 Body 또는 Footer 영역 선택 시 포커스 되는 형식을 설정합니다.",
    "validation" : [
        "focusMode 값에 따라 포커스/선택 스타일, 키보드 이동, 다중 선택, DataList rowPosition 동기화 등 포커스 시스템 전체의 활성/적용 범위가 결정됩니다.",
        "focusMode='cell'(기본값) 이면 선택된 Cell 이 포커스되며, 포커스 Cell 의 <td> 요소에 'focusedTd' CSS 클래스가 적용되고 selectedCellColor 배경색, 마우스오버 시 selectedCellOverColor 가 적용됩니다.",
        "focusMode='row' 이면 선택된 Row 가 포커스되며, 포커스 Row 의 모든 <td> 요소에 'focusedTr' CSS 클래스가 적용되고 selectedRowColor 배경색, 마우스오버 시 selectedRowOverColor 가 적용됩니다.",
        "focusMode='both' 이면 Cell 과 Row 가 모두 포커스되며, 포커스 Row 의 모든 <td> 요소에 'focusedTr', 포커스 Cell 의 <td> 요소에 'focusedTd' 가 추가됩니다. 포커스 Cell 은 selectedCellColor, 같은 Row 의 다른 Cell 은 selectedRowColor 가 적용됩니다.",
        "focusMode='none' 이면 포커스 처리가 되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - focusMode 가 시험 대상이므로 con_focusMode 콤보값으로 createCList 반영
//  - selectedCellColor=red / selectedRowColor=blue 로 구분색 하드코딩 (cell/row/both 결과를 배경색으로 구분)
//  - selectedCellOverColor / selectedRowOverColor 도 별도 구분색 하드코딩 (오버색 확인용)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (focusMode 는 con 콤보값, 색상은 구분 가능하도록 하드코딩)
    let properties = {
        focusMode             : con_focusMode.getValue(),
        selectedCellColor     : "red",
        selectedRowColor      : "blue",
        selectedCellOverColor : "magenta",
        selectedRowOverColor  : "lime"
    };
    let cList = $c.gcm.createCList(properties);
    // 셀 클릭(포커스)/마우스오버 시 선택 상태·색상을 출력하기 위해 이벤트 등록
    let eList = $c.gcm.createEList(["oncellclick", "onbodymouseover"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="focusMode=' + con_focusMode.getValue() + ' / selectedCellColor=red / selectedRowColor=blue / selectedCellOverColor=magenta / selectedRowOverColor=lime 로 GridView 생성"', '', 'label1');

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (4컬럼 Body 그리드)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="focusMode 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 포커스된 셀/Row 의 선택 상태를 focusMode 기준으로 출력하는 공통 함수
//  - 포커스 <td> 의 CSS 클래스(focusedTd / focusedTr 유무) + computed 배경색을 함께 표시
//  - cell : 포커스 Cell <td> 에 focusedTd, 배경 selectedCellColor(red)
//  - row  : 포커스 Row 모든 <td> 에 focusedTr, 배경 selectedRowColor(blue)
//  - both : 포커스 Row 에 focusedTr + 포커스 Cell 에 focusedTd, 포커스 Cell=red / 다른 Cell=blue
//  - none : 클래스 없음, 강조 없음
scwin.printFocusState = function (rowIndex, colIndex) {
    let mode = con_focusMode.getValue();
    let bottom = wf_body_bottom.getObj("scwin");

    let getTd = function (r, c) {
        return document.querySelector("td[id*='mf_target1_cell_" + r + "_" + c + "']");
    };
    let hasClass = function (td, cls) {
        return td ? td.classList.contains(cls) : false;
    };
    let getColor = function (td) {
        return td ? window.getComputedStyle(td).backgroundColor : "(cell 없음)";
    };

    let focusTd = getTd(rowIndex, colIndex);

    if (mode === 'row') {
        // 포커스 Row 모든 td 에 focusedTr, 배경 selectedRowColor(blue)
        let otherTd = getTd(rowIndex, (colIndex === 0) ? 1 : 0);
        bottom.setReturnValue("[focusMode=row] 포커스 Row(" + rowIndex + ") 전체에 focusedTr 적용");
        bottom.setReturnValue("[클릭 Cell(" + rowIndex + "," + colIndex + ")] focusedTr=" + hasClass(focusTd, 'focusedTr') + " / focusedTd=" + hasClass(focusTd, 'focusedTd') + " / 배경색 " + getColor(focusTd));
        bottom.setReturnValue("[동일 Row 다른 Cell(" + rowIndex + "," + ((colIndex === 0) ? 1 : 0) + ")] focusedTr=" + hasClass(otherTd, 'focusedTr') + " / 배경색 " + getColor(otherTd));
    } else if (mode === 'both') {
        // 포커스 Row 에 focusedTr + 포커스 Cell 에 focusedTd
        let otherTd = getTd(rowIndex, (colIndex === 0) ? 1 : 0);
        bottom.setReturnValue("[focusMode=both] 포커스 Row(" + rowIndex + ") 에 focusedTr + 포커스 Cell 에 focusedTd 적용");
        bottom.setReturnValue("[포커스 Cell(" + rowIndex + "," + colIndex + ")] focusedTd=" + hasClass(focusTd, 'focusedTd') + " / focusedTr=" + hasClass(focusTd, 'focusedTr') + " / 배경색(selectedCellColor) " + getColor(focusTd));
        bottom.setReturnValue("[동일 Row 다른 Cell(" + rowIndex + "," + ((colIndex === 0) ? 1 : 0) + ")] focusedTr=" + hasClass(otherTd, 'focusedTr') + " / 배경색(selectedRowColor) " + getColor(otherTd));
    } else if (mode === 'none') {
        // 포커스 처리 안 됨 : 클래스 없음, 강조 없음
        bottom.setReturnValue("[focusMode=none] 포커스 처리 안 됨");
        bottom.setReturnValue("[클릭 Cell(" + rowIndex + "," + colIndex + ")] focusedTd=" + hasClass(focusTd, 'focusedTd') + " / focusedTr=" + hasClass(focusTd, 'focusedTr') + " / 배경색 " + getColor(focusTd));
    } else {
        // cell (기본값) : 포커스 Cell <td> 에 focusedTd, 배경 selectedCellColor(red)
        bottom.setReturnValue("[focusMode=cell] 선택된 Cell 에 focusedTd 적용");
        bottom.setReturnValue("[포커스 Cell(" + rowIndex + "," + colIndex + ")] focusedTd=" + hasClass(focusTd, 'focusedTd') + " / focusedTr=" + hasClass(focusTd, 'focusedTr') + " / 배경색(selectedCellColor) " + getColor(focusTd));
    }
}



// oncellclick : 사용자가 셀을 클릭하면 발생. 클릭한 셀이 포커스되며,
//  현재 focusMode 기준 선택 상태(클래스/배경색)를 출력
scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();
    scwin.printFocusState(rowIndex, columnIndex);
}



// onbodymouseover : 마우스가 Body Cell 위에 오버될 때 발생.
//  포커스된 셀/Row 위에 오버되면 over색(selectedCellOverColor / selectedRowOverColor)이 적용됨.
//  focusMode 기준 오버색 적용 결과(배경색)를 출력
scwin.target1_onbodymouseover = function (info) {
    let mode = con_focusMode.getValue();
    let bottom = wf_body_bottom.getObj("scwin");
    let r = info.rowIndex;
    let c = info.colIndex;

    let td = document.querySelector("td[id*='mf_target1_cell_" + r + "_" + c + "']");
    if (!td) return;
    let bg = window.getComputedStyle(td).backgroundColor;

    bottom.btn_clear_onclick();
    if (mode === 'none') {
        bottom.setReturnValue("[focusMode=none 마우스오버] Cell(" + r + "," + c + ") 강조 없음 / 배경색 " + bg);
    } else if (mode === 'row') {
        bottom.setReturnValue("[focusMode=row 마우스오버] Cell(" + r + "," + c + ") selectedRowOverColor 적용 / 배경색 " + bg);
    } else if (mode === 'both') {
        bottom.setReturnValue("[focusMode=both 마우스오버] Cell(" + r + "," + c + ") over색 적용 / 배경색 " + bg);
    } else {
        bottom.setReturnValue("[focusMode=cell 마우스오버] Cell(" + r + "," + c + ") selectedCellOverColor 적용 / 배경색 " + bg);
    }
}
